import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const root = new Group();
  const owned = [];
  const timelines = [];
  let loadedTexture = null;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    uv().y
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  owned.push(backdrop);

  const surfaceGeometry = new PlaneGeometry(5.8, 1.35);
  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.96
  });
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.set(0, 0, -0.35);
  root.add(surface);
  owned.push(surface);

  const accentGeometry = new PlaneGeometry(0.055, 0.78);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-2.7, 0, -0.18);
  root.add(accent);
  owned.push(accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const typography = item.typography ?? {};
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: typography.fontSize ?? 42,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 1.2,
      maxWidthPx: 900
    });

    textObject.position.set(-2.35, -0.02, 0.05);
    root.add(textObject);
  }

  if (config.imageUrl) {
    const imageGeometry = new PlaneGeometry(1.65, 1.05);
    const imageMaterial = new MeshBasicNodeMaterial({
      color: '#e8ecf2',
      transparent: true
    });
    const imageMesh = new Mesh(imageGeometry, imageMaterial);
    imageMesh.position.set(2.0, 0, 0.02);
    imageMesh.scale.set(0.001, 0.001, 0.001);
    root.add(imageMesh);
    owned.push(imageMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      loadedTexture = texture;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;

      const entrance = gsap.timeline();
      timelines.push(entrance);
      entrance.to(imageMesh.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.7,
        ease: 'power3.out'
      });
    }).catch(() => {
      imageMesh.visible = false;
    });
  }

  const settle = gsap.timeline();
  timelines.push(settle);
  settle.fromTo(
    surface.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const timeline of timelines) timeline.kill();

    for (const object of owned) {
      if (object.geometry) object.geometry.dispose();

      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        for (const material of materials) {
          material.dispose();
        }
      }

      root.remove(object);
    }

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
  };

  return root;
}
